paragraph.math:
$$\begin{matrix}
    {E\lbrack X\rbrack\, = \underset{x}{\sum\,}{xp(x)}} & = & {\underset{x}{\sum\,}{xP(X = x)}} \\
     & = & {\underset{x}{\sum\,}x\underset{n = 1}{\overset{\text{∞}}{\sum\,}}{P\left( X = x \middle| F_{n} \right)P\left( F_{n} \right)}} \\
     & = & {\underset{n = 1}{\overset{\text{∞}}{\sum\,}}{P\left( F_{n} \right)}\underset{x}{\sum\,}{xP\left( X = x \middle| F_{n} \right)}} \\
     & = & {\underset{n = 1}{\overset{\text{∞}}{\sum\,}}{E\left\lbrack X \middle| F_{n} \right\rbrack P\left( F_{n} \right)}}
    \end{matrix}$$

$$D\textbf{q} = \,\,\begin{bmatrix}
    t_{11} & 0 & \cdots & 0 \\
    0 & t_{22} & \cdots & 0 \\
     \vdots & \vdots & \ddots & \vdots \\
    0 & 0 & \cdots & t_{nn}
    \end{bmatrix}\begin{bmatrix}
    q_{1} \\
    q_{2} \\
     \vdots \\
    q_{n}
    \end{bmatrix}\, = \,\,\begin{bmatrix}
    {t_{11}q_{1}} \\
    {t_{22}q_{2}} \\
     \vdots \\
    {t_{nn}q_{n}}
    \end{bmatrix}$$

$$\begin{matrix}
    a_{ij} & {= P\left( \text{absorption at~}i \right)} \\
     & {= \underset{k}{\sum\,}P\left( \text{absorption at~}i \middle| X_{1} = k \right)P\left( {X_{1} = k} \right)} \\
     & {= 1 \cdot P\left( {X_{1} = i} \right)\, + \underset{k\,\,\,\text{transient}}{\sum\,}P\left( \text{absorption at~}i \middle| X_{1} = k \right)P\left( {X_{1} = k} \right)} \\
     & {= p_{ij} + \underset{k\,\,\,\text{transient}}{\sum\,}a_{ik}p_{kj}}
    \end{matrix}$$
